import { test, expect } from '@playwright/test';

test.describe('Mobile Navigation Collapse', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should collapse navigation into hamburger menu on mobile view', async ({ page }) => {
    // Set viewport to mobile
    await page.setViewportSize({ width: 375, height: 812 });

    // Verify hamburger menu is visible
    const hamburgerMenu = page.getByRole('button', { name: /menu/i });
    await expect(hamburgerMenu).toBeVisible();

    // Verify navigation links are collapsed
    const navLinks = page.getByRole('link', { name: /home|about|services|contact/i });
    await expect(navLinks).not.toBeVisible();

    // Verify hamburger menu icon is visible
    const menuIcon = page.getByRole('button', { name: /menu/i });
    await expect(menuIcon).toBeVisible();

    // Verify navigation menu opens when hamburger is clicked
    await hamburgerMenu.click();
    await expect(navLinks).toBeVisible();

    // Verify navigation menu closes when hamburger is clicked again
    await hamburgerMenu.click();
    await expect(navLinks).not.toBeVisible();

    // Verify hamburger menu is still visible
    await expect(menuIcon).toBeVisible();

    // Verify navigation menu is responsive and closes on click outside
    const outsideClick = page.locator('body');
    await outsideClick.click();
    await expect(navLinks).not.toBeVisible();
    await expect(menuIcon).toBeVisible();
  });

  test('should handle edge case: navigation menu opens on page load on mobile', async ({ page }) => {
    // Set viewport to mobile
    await page.setViewportSize({ width: 375, height: 812 });

    // Verify hamburger menu is visible on page load
    const hamburgerMenu = page.getByRole('button', { name: /menu/i });
    await expect(hamburgerMenu).toBeVisible();

    // Verify navigation links are collapsed
    const navLinks = page.getByRole('link', { name: /home|about|services|contact/i });
    await expect(navLinks).not.toBeVisible();

    // Verify hamburger menu icon is visible
    const menuIcon = page.getByRole('button', { name: /menu/i });
    await expect(menuIcon).toBeVisible();

    // Verify navigation menu opens when hamburger is clicked
    await hamburgerMenu.click();
    await expect(navLinks).toBeVisible();

    // Verify navigation menu closes when hamburger is clicked again
    await hamburgerMenu.click();
    await expect(navLinks).not.toBeVisible();

    // Verify hamburger menu is still visible
    await expect(menuIcon).toBeVisible();

    // Verify navigation menu closes when clicking outside
    const outsideClick = page.locator('body');
    await outsideClick.click();
    await expect(navLinks).not.toBeVisible();
    await expect(menuIcon).toBeVisible();

    // Verify navigation menu is responsive and closes on page load
    await expect(navLinks).not.toBeVisible();
    await expect(menuIcon).toBeVisible();
  });
});
